assignments.value:
={{ (() => {
  // Validar contrato mínimo emitido por Neon Function bulletinnotify
  const body = $('Webhook (Publicación Cartelera)').first().json.body || {};
  const errors = [];
  const REQUIRED_SCHEMA = {
    record_id: 'uuid string',
    audience_scope: 'institution | mention',
    recipients: 'non-empty array of { email, name }',
    email: '{ subject: string, html: string }'
  };

  if (typeof body.record_id !== 'string' || body.record_id.trim().length < 8) {
    errors.push({ field: 'record_id', message: 'record_id requerido' });
  }
  if (body.audience_scope !== 'institution' && body.audience_scope !== 'mention') {
    errors.push({ field: 'audience_scope', message: 'audience_scope debe ser institution o mention' });
  }
  const recipients = Array.isArray(body.recipients) ? body.recipients : [];
  const validRecipients = recipients.filter((r) => r && typeof r.email === 'string' && r.email.includes('@'));
  if (validRecipients.length === 0) {
    errors.push({ field: 'recipients', message: 'Debe incluir al menos un destinatario con correo válido' });
  }
  if (!body.email || typeof body.email.subject !== 'string' || !body.email.subject.trim()) {
    errors.push({ field: 'email.subject', message: 'Asunto del correo requerido' });
  }
  if (!body.email || typeof body.email.html !== 'string' || !body.email.html.trim()) {
    errors.push({ field: 'email.html', message: 'Contenido HTML del correo requerido' });
  }

  return {
    valid: errors.length === 0,
    validationError: errors.length > 0 ? 'Payload de publicación de cartelera inválido.' : null,
    details: errors,
    requiredSchema: REQUIRED_SCHEMA
  };
})() }}

parameters.responseBody:
={{ (() => {
  const v = $('Validar Payload Cartelera').first().json.validation || {};
  return {
    ok: false,
    error: 'validation_error',
    message: v.validationError || 'Payload inválido.',
    details: v.details || [],
    request_schema: v.requiredSchema || {}
  };
})() }}

={{ (() => {
  const body = $('Webhook (Publicación Cartelera)').first().json.body || {};
  const items = $input.all();
  const messageIds = [];
  for (const item of items) {
    const data = item.json || {};
    if (Array.isArray(data.message_ids)) {
      for (const id of data.message_ids) {
        if (id) messageIds.push(String(id));
      }
    } else if (data.messageId) {
      messageIds.push(String(data.messageId));
    } else if (data.id) {
      messageIds.push(String(data.id));
    }
  }
  return {
    ok: true,
    workflow_run_id: body.workflow_run_id || null,
    record_id: body.record_id || null,
    audience_scope: body.audience_scope || null,
    audience_label: body.audience_label || null,
    sender: 'notificaciones@etcandresbello.org',
    sent_count: items.length,
    message_ids: messageIds
  };
})() }}

